@container(max-width:580px) { .ds .ds-search-form { grid-template-columns:minmax(0,1fr) auto; } .ds .ds-search-form > .ds-field { grid-column:1/-1; } }
/* Looks. Labels hidden by a look stay in the page for screen readers. */
.ds .ds-search-module[data-look="pill"] :is(.ds-field > label,.ds-select-field > span),.ds .ds-chip-group > legend,.ds .ds-chip input { position:absolute; width:var(--p-size-hairline); height:var(--p-size-hairline); overflow:hidden; clip-path:inset(50%); white-space:nowrap; }
/* 02 pill: query, status and button share one rounded bar */
.ds .ds-search-module[data-look="pill"] .ds-search-form { grid-template-columns:minmax(0,1fr) auto auto; align-items:center; gap:var(--p-space-2xs); padding:var(--p-space-2xs) var(--p-space-2xs) var(--p-space-2xs) var(--p-space-sm); border:var(--p-border-width) solid var(--p-control-border); border-radius:var(--p-radius-full); background:var(--p-bg); box-shadow:var(--p-inset); }
