.ds .ds-search-module[data-look="pill"] .ds-search-form > .ds-button { border-radius:var(--p-radius-full); }
@container(max-width:420px) { .ds .ds-search-module[data-look="pill"] .ds-search-form > .ds-button { gap:0; padding-inline:var(--p-space-sm); font-size:0; } }
/* 03 chips: status as a row of chips under the query */
.ds .ds-search-module[data-look="chips"] .ds-search-form { grid-template-columns:minmax(0,1fr) auto; }
.ds .ds-search-module[data-look="chips"] .ds-search-form > .ds-field { grid-column:auto; }
.ds .ds-chip-group { grid-column:1/-1; order:3; display:flex; flex-wrap:wrap; gap:var(--p-space-xs); min-width:0; margin:0; padding:0; border:0; }
.ds .ds-chip { position:relative; display:inline-flex; align-items:center; gap:var(--p-space-xs); min-height:var(--p-control-size-sm); padding:0 var(--p-space-md); border:var(--p-border-width) solid var(--p-control-border); border-radius:var(--p-radius-full); background:var(--p-bg); font-size:var(--p-text-body); cursor:pointer; }
.ds .ds-chip:has(:checked) { border-color:var(--p-accent); background:var(--p-accent); color:var(--p-on-accent); font-weight:var(--p-weight-semibold); }
