/* list: results as rows instead of tiles */
.ds .ds-search-module[data-look="list"] .ds-results { grid-template-columns:minmax(0,1fr); gap:0; }
.ds .ds-search-module[data-look="list"] .ds-card { flex-flow:row wrap; align-items:center; border:0; border-radius:0; background:transparent; box-shadow:none; }
.ds .ds-search-module[data-look="list"] .ds-card-body { flex:1 1 calc(var(--p-space-unit) * 40); padding:var(--p-space-md) 0; }
.ds .ds-search-module[data-look="list"] .ds-card h3 { margin-top:var(--p-space-2xs); font-size:var(--p-text-md); }
.ds .ds-search-module[data-look="list"] .ds-divider { display:none; }
.ds .ds-search-module[data-look="list"] .ds-card-actions { padding:var(--p-space-xs) 0 var(--p-space-xs) var(--p-space-sm); }
.ds .ds-search-module[data-look="list"] .ds-results { border-top:var(--p-border-width) solid var(--p-line); }
.ds .ds-search-module[data-look="list"] .ds-card { border-bottom:var(--p-border-width) solid var(--p-line); }
/* 07 feature: the first result spans the row with a bigger title */
.ds .ds-search-module[data-look="feature"] .ds-results > :first-child { grid-column:1/-1; }
.ds .ds-search-module[data-look="feature"] .ds-results > :first-child h3 { font-size:var(--p-text-lg); line-height:var(--p-leading-snug); }
