.ds .ds-search-module[data-look="picker"] .ds-search-form { grid-template-columns:minmax(0,1fr); }
.ds .ds-search-module[data-look="picker"] .ds-results { grid-template-columns:minmax(0,1fr); gap:0; border-top:var(--p-border-width) solid var(--p-line); }
.ds .ds-search-module[data-look="picker"] .ds-card { position:relative; display:grid; grid-template-columns:var(--p-control-size-sm) minmax(0,1fr) auto; align-items:center; gap:var(--p-space-sm); padding:var(--p-space-xs) var(--p-space-2xs); border:0; border-bottom:var(--p-border-width) solid var(--p-line); border-radius:0; background:transparent; box-shadow:none; }
.ds .ds-search-module[data-look="picker"] .ds-card-media { display:grid; place-items:center; flex:none; width:var(--p-control-size-sm); height:var(--p-control-size-sm); margin:0; aspect-ratio:auto; border-radius:var(--p-radius-circle); background:var(--p-soft); color:var(--p-ink); font-weight:var(--p-weight-bold); }
.ds .ds-search-module[data-look="picker"] .ds-card-body { display:flex; flex-wrap:wrap; align-items:center; gap:var(--p-space-3xs) var(--p-space-xs); padding:0; min-width:0; }
